(x, y, t) => {
  const cx = 240, cy = 120;
  const wx = Math.sin(x*0.02+t*0.3)*15 + Math.cos(y*0.015-t*0.2)*10 + Math.sin((x+y)*0.01+t*0.5)*8;
  const wy = Math.cos(y*0.02-t*0.25)*15 + Math.sin(x*0.018+t*0.35)*10 + Math.cos((x-y)*0.012-t*0.4)*8;
  const sx = x+wx, sy = y+wy;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0, 1.0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7, 0.8],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3, 1.2],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5, 0.9],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6, 1.1],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9, 0.7],
    [60+Math.sin(t*0.45+3)*70, 40+Math.cos(t*0.65)*50, 0.11, 2.1, 1.3],
    [400+Math.cos(t*0.55+2)*60, 200+Math.sin(t*0.75+1)*70, 0.05, 1.8, 0.85]
  ];
  let aS=0, iS=0, cross=0;
  for (let a=0; a<src.length; a++) {
    const [sX,sY,f,sp,w] = src[a];
    const d = Math.sqrt((sx-sX)**2+(sy-sY)**2);
    const wave = Math.sin(d*f-t*sp)*w;
    aS += wave;
    iS += Math.sin(d*f*0.7+t*sp*0.6+1.5)*w;
    for (let b=a+1; b<src.length; b++) {
      const [sX2,sY2,f2,sp2,w2] = src[b];
      const d2 = Math.sqrt((sx-sX2)**2+(sy-sY2)**2);
      cross += Math.sin(d*f-t*sp)*Math.sin(d2*f2-t*sp2)*0.15*w*w2;
    }
  }
  const n = src.length;
  const act = aS/n, inh = iS/n, crossN = cross/(n*n);
  const bg = (Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1))/2
    + Math.sin((sx+sy)*0.12+t*2.5)*0.2 + Math.sin((sx-sy)*0.1-t*2)*0.2
    + Math.sin(sx*0.07+Math.sin(sy*0.05+t)*3+t*0.6)*0.15;
  const dist = Math.sqrt((sx-cx)**2+(sy-cy)**2), ang = Math.atan2(sy-cy, sx-cx);
  const spiral = (Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2))*0.4
    + Math.sin(dist*0.03-ang*5+t*0.8)*0.2;
  const ring = Math.sin(dist*0.08-t*2.0)*Math.exp(-dist*0.005)*0.3;
  const reaction = Math.tanh((act-inh*0.7+bg*0.3+spiral+crossN*2.0+ring)*2.2);
  const cellA = Math.sin(sx*0.15)*Math.sin(sy*0.15);
  const cellB = Math.sin((sx+sy)*0.1+t)*0.5;
  const cellC = Math.sin(sx*0.12-t*0.3)*Math.cos(sy*0.13+t*0.4)*0.4;
  const cell = Math.tanh((cellA+cellB+cellC)*1.5)*0.25;
  const turbulence = Math.sin(Math.sin(sx*0.02+t)*5+sy*0.03)*Math.sin(Math.cos(sy*0.025-t*0.7)*4+sx*0.035)*0.15;
  const blend = reaction*0.6+cell*0.2+turbulence*0.2;
  const v = blend*0.5+0.5;
  const glow = Math.max(0, 1.0-Math.abs(reaction)*0.6)*0.15;
  const vf = Math.min(1, v+glow);
  const pal = [
    [5,10,42],[12,35,78],[8,72,98],[15,115,115],[35,158,140],
    [130,185,120],[210,195,75],[225,150,65],[200,95,55],
    [155,50,60],[90,22,55],[35,12,45],[5,10,42]
  ];
  const idx = vf*(pal.length-1), i = Math.min(idx|0, pal.length-2), f = idx-i;
  const lum = 0.75+Math.sin(reaction*Math.PI)*0.25;
  const edge = Math.abs(reaction)>0.65?1.2:Math.abs(reaction)>0.4?1.08:1.0;
  const crossGlow = Math.max(0, crossN)*0.3;
  return [
    Math.min(255, (pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*(lum*edge+crossGlow))|0,
    Math.min(255, (pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*(lum*edge+crossGlow*0.8))|0,
    Math.min(255, (pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*(lum*edge+crossGlow*0.5))|0
  ];
}
